WITH with_dims AS (SELECT e.*, a.opened_date FROM transactions e LEFT JOIN accounts a ON e.account_id = a.id), joined AS (SELECT a.*, p.status, p.opened_date AS account_opened_date, p.balance FROM with_dims a LEFT JOIN accounts p ON a.account_id = p.id), joined_transactions AS (SELECT e.*, d.balance AS account_balance, d.account_type FROM joined e LEFT JOIN accounts d ON e.account_id = d.id), enriched AS (SELECT e.id, e.account_id, e.txn_type, e.amount, e.merchant, e.opened_date, e.status, e.account_opened_date, a.balance AS account_balance_2, a.account_type AS account_account_type, a.opened_date AS account_opened_date_2 FROM joined_transactions e LEFT JOIN accounts a ON e.account_id = a.id), metrics AS (SELECT *, LAG(account_balance_2) OVER w_hist AS prev_account_balance_2, LEAD(account_balance_2) OVER w_hist AS next_account_balance_2, LAG(amount) OVER w_hist AS prev_amount, LEAD(amount) OVER w_hist AS next_amount, ROW_NUMBER() OVER w_hist AS seq_no FROM enriched WINDOW w_hist AS (PARTITION BY txn_type, merchant ORDER BY opened_date, id)), pivoted AS (SELECT * FROM (SELECT account_account_type, merchant, next_amount FROM metrics) src PIVOT (MAX(next_amount) FOR merchant IN ('Lazada' AS lazada, '7-Eleven' AS v_7_eleven))) SELECT account_account_type, lazada, v_7_eleven FROM pivoted ORDER BY account_account_type
